  batch: number | null;
  /** The claim's lines, oldest first, each as <label> <qty> x <unit>; empty when it has none. A claim
   *  with lines has them added up as its amount. */
  lines: string[];
  /** Whether a steward waived the claim's late charge: it bears none from then on. */
  waived: boolean;
  /** Whether the claim itself is held: it still counts in every total. */
  held: boolean;
  /** The shares of the claim other people on the sheet hold, in the order it was shared: each the
   *  holder's id and their share percent (two decimals). */
  shares: ClaimShare[];
  /** The user a steward assigned the claim's review to; null when no one was. */
  reviewAssignee: string | null;
}

/** A share of a claim another person holds: the holder's id and their share percent (two decimals). */
export interface ClaimShare {
  personId: number;
  share: string;
}

/** A holder's part of a claim's due in cents: the due times their share divided by 100, rounded
 *  half to even. */
export function sharePartCents(dueCents: number, share: string): number {
  // The share in hundredths of a percent, so the part is dueCents * hundredths / 10,000.
  const hundredths = Math.round(Number(share) * 100);
  const scaled = dueCents * hundredths;
  const sign = scaled < 0 ? -1 : 1;
  const abs = Math.abs(scaled);
  let whole = Math.floor(abs / 10_000);
  const rest = abs - whole * 10_000;
  if (rest > 5_000 || (rest === 5_000 && whole % 2 !== 0)) whole += 1;
  return sign * whole;
}

/** What a split did: the claim that kept the rest of its amount, and the new claim split off it. */
interface Split {
  kept: Claim;
  added: Claim;
}

/** Whether a claim is deferred on the sheet's today: today is before the date it was deferred until
 *  and no statement binds it. A deferral takes effect only once the binding ends, so a claim settled
 *  while bound is deferred too once unbound. From that date on it is a claim like any other. */
export function deferred(claim: Claim, today: string | null): boolean {
  return (claim.status === 'OPEN' || claim.status === 'SETTLED') && !claim.stated
    && claim.deferredUntil !== null && today !== null && today < claim.deferredUntil;
}

/** The status a claim had at the end of a day, as its status log records it: the last status it
 *  moved to on or before that day; null when it was added after it. */
export function statusAsOf(claim: Claim, day: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of claim.log) {
    const match = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=\S+$/.exec(line);
    if (match && match[2] <= day) status = match[1] as ClaimStatus;
  }
  return status;
}

/** Whether a claim is a correction: its amount is negative. */
export function isCorrection(claim: Claim): boolean {
  return cents(claim.amount) < 0;
}

/** Whether a claim counts toward what is claimed and due: only OPEN, PENDING and SETTLED ones do. */
export function counts(claim: Claim): boolean {
  return isOpen(claim) || claim.status === 'SETTLED';
}

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** An amount in cents, from the two-decimal string the server sends. */
export function cents(amount: string): number {
  return Math.round(Number(amount) * 100);
}

/** What a late charge works from: the sheet's late percent (two decimals) in force on a date, its today and
 *  a claim's grace days (see graceOn in the settings); and what a claim's figures round by: the sheet's
 *  rounding mode in force on a date (half-up or half-even; null for none), else its policy date (blank for
 *  its today). */
export interface Late {
  pct: (date: string) => string;
  today: string | null;
  policyDate: string;
  rounding: (date: string) => string | null;
  grace: (claim: Claim) => number;
}

/** Whether a claim's live figures round half up: by the rounding mode in force on the date it rounds by
 *  when one is; else it rounds by a date before the sheet's policy date (its today when the policy date
 *  is blank); otherwise they round half to even. */
function roundsHalfUp(claim: Claim, late: Late): boolean {
  const mode = late.rounding(claim.roundsBy);
  if (mode !== null) return mode === 'half-up';
  const policy = late.policyDate !== '' ? late.policyDate : late.today;
  return policy !== null && claim.roundsBy < policy;
}

/** A claim's figure in cents: the due a statement bound it to; otherwise its amount times the
 *  rate in force on its date among its grade's rates; null when it has no figure. The floor is not applied here (see claimDueCents). */
function figureCents(claim: Claim, rates: Rate[], halfUp: boolean): number | null {
  if (claim.stated) return claim.statedDue === null ? null : cents(claim.statedDue);
  const rate = rateOn(rates, claim.date);
  if (rate === null) return null;
  return dueCents(cents(claim.amount), rate, halfUp);
}

/** A claim's due in cents: the due fixed when it was settled; otherwise its floored figure (the greater of
 *  the sheet's floor in force on its date and its figure; none for a correction) plus its late charge on
 *  that floored figure: for every full 30 days an OPEN or PENDING claim is overdue, the late percent in force
 *  on that boundary (its due-by plus 30, 60, 90 ... days) of the floored figure plus the charges of the
 *  boundaries before it (compounding), rounded
 *  like a due, the charges added up (a statement binds the due,
 *  charge included; settling freezes the due; a correction or a waived claim has none); null when it has no
 *  figure. */
export function claimDueCents(claim: Claim, rates: Rate[], floor: (date: string) => number, late: Late): number | null {
  if (claim.settledDue !== null) return cents(claim.settledDue);
  if (claim.stated) return claim.statedDue === null ? null : cents(claim.statedDue);
  const halfUp = roundsHalfUp(claim, late);
  const raw = figureCents(claim, rates, halfUp);
  if (raw === null) return null;
  if (isCorrection(claim)) return raw;
