  for (let boundary = 1; boundary <= periods; boundary++) {
    const pct = late.pct(plusDays(claim.dueBy, grace + 30 * boundary));
    if (cents(pct) !== 0) charge += dueCents(figure + charge, pct, halfUp);
  }
